-- Seedance — Генерація відео
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'seed.bytedance.com/en/seedance' OR LOWER(`name`) = LOWER('Seedance'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Seedance', NULL, 'https://seed.bytedance.com/en/seedance', NULL, NULL, 'Модель генерації відео від команди ByteDance Seed: створює відео з тексту чи зображення, зокрема розповіді з кількох послідовних кадрів, у роздільній здатності 1080p, з плавним рухом і різними візуальними стилями.', 'A video generation model from the ByteDance Seed team: it creates video from text or an image, including stories made of several connected shots, in 1080p with smooth motion and a range of visual styles.', 'Seedance — сімейство моделей для створення відео, яке розробляє дослідницька команда ByteDance Seed. Модель перетворює текстовий опис або зображення на відео у 1080p і вміє будувати оповідь із кількох пов''язаних кадрів, зберігаючи головного героя, стиль і атмосферу при переходах між сценами. Вона стабільно передає як дрібні рухи й міміку, так і динамічні сцени, і точно слідує підказкам щодо стилю — від фотореалізму до ілюстрації чи ефекту фетрової текстури. Спробувати модель можна на сайті команди, а розробникам доступний API. Seedance також використовують як одну з моделей у багатьох сторонніх сервісах генерації відео.', 'Seedance is a family of video generation models developed by the ByteDance Seed research team. The model turns a text description or an image into 1080p video and can build a story out of several connected shots, keeping the main character, style and mood consistent across scene changes. It handles both subtle movements and expressions and dynamic scenes, and closely follows style prompts, from photorealism to illustration or a felt-texture look. You can try the model on the team''s website, and developers can use an API. Seedance is also offered as one of the models inside many third-party video generation services.', 'Відео з тексту чи зображення
Розповідь із кількох послідовних кадрів
Збереження героя й стилю між сценами
Роздільна здатність 1080p
Різні візуальні стилі
Доступ через API', 'Video from text or an image
Stories made of several connected shots
Consistent character and style across scenes
1080p resolution
A range of visual styles
API access', 'Автори відео, студії й розробники, які вбудовують генерацію відео у власні продукти.', 'Video creators, studios and developers who build video generation into their own products.', 'web', 'basic', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
SET @pid = (SELECT `id` FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'seed.bytedance.com/en/seedance' OR LOWER(`name`) = LOWER('Seedance')) ORDER BY `id` LIMIT 1);
