-- Kin — AI-асистенти
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'mykin.ai' OR LOWER(`name`) = LOWER('Kin'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Kin', NULL, 'https://mykin.ai', NULL, NULL, 'Персональний AI-застосунок, що поступово вивчає ваш контекст і працює як рада з п''яти AI-радників — робота, стосунки, цінності, тіло й енергія, соціальна впевненість — плюс щоденні структуровані сесії.', 'A personal AI app that gradually learns your context and works as a board of five AI advisors (work, relationships, values, body and energy, social confidence) plus daily structured sessions.', 'Kin будує стале, з часом доповнюване розуміння того, хто ви є, тож кожна нова розмова продовжує попередню, а поради враховують ваші звички, стосунки й сліпі зони. Основа застосунку — рада з п''яти AI-радників, кожен із яких дивиться на ситуацію під своїм кутом: робота й продуктивність, стосунки, цінності та сенс, тіло й енергія, соціальна впевненість. Вони знають ваш контекст і ставлять під сумнів ваші припущення. Щоденні сесії — це структуровані розмови глибші за звичайний чат: підготуватися до дня, розібрати рішення чи зрозуміти, що заважає рухатися далі. Застосунок позиціонується як приватний за задумом і доступний на мобільних пристроях.', 'Kin builds a persistent, evolving understanding of who you are, so every new conversation picks up where the last one ended and the advice takes your habits, relationships and blind spots into account. At its core is a board of five AI advisors, each looking at a situation from its own angle: work and productivity, relationships, values and meaning, body and energy, and social confidence. They know your context and challenge your assumptions. Daily sessions are structured conversations that go deeper than a regular chat: prepare for the day, unpack a decision or figure out what is holding you back. The app is positioned as private by design and is available on mobile devices.', 'Пам''ять про ваш особистий контекст
Рада з п''яти AI-радників за темами життя
Щоденні структуровані сесії
Підготовка до дня й розбір рішень
Мобільний застосунок
Акцент на приватності', 'Memory of your personal context
A board of five AI advisors by life area
Daily structured sessions
Day preparation and decision reviews
Mobile app
Privacy focus', 'Люди, які хочуть персонального AI-коуча для особистих і робочих питань.', 'People who want a personal AI coach for personal and work matters.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
