-- Biela.dev — No-code / Low-code
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'biela.dev' OR LOWER(`name`) = LOWER('Biela.dev'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Biela.dev', NULL, 'https://biela.dev', NULL, NULL, 'AI-конструктор сайтів і застосунків без коду: опишіть ідею підказкою, і Biela.dev збудує проєкт, який можна розгорнути, завантажити чи підключити до власного домену; є шаблони й безкоштовний тариф.', 'A no-code AI builder for websites and apps: describe your idea in a prompt and Biela.dev builds a project you can deploy, download or connect to your own domain; templates and a free plan are available.', 'Biela.dev дозволяє перетворити ідею на робочий сайт чи застосунок без досвіду програмування. Ви описуєте, що потрібно, а платформа будує проєкт за допомогою обраної мовної моделі; почати можна і з готового шаблону, наприклад лендінгу. У робочому середовищі є чат для роботи з кодом і режим «приватного технічного директора» для планування. Проєкти можна інтегрувати з Supabase, ділитися ними, завантажувати, розгортати й підключати до власного домену. Безкоштовний тариф дає кілька підказок і зображень для перших проєктів; платні плани додають більше токенів, ширше контекстне вікно й можливості публікації. Також є партнерська програма та рішення для компаній.', 'Biela.dev lets you turn an idea into a working website or app without coding experience. You describe what you need and the platform builds the project using the language model you choose; you can also start from a ready-made template such as a landing page. The workspace includes a code chat and a ''private CTO'' mode for planning. Projects can be integrated with Supabase, shared, downloaded, deployed and connected to a custom domain. The free plan gives a few prompts and images for first projects; paid plans add more tokens, a larger context window and publishing options. There is also an affiliate program and an offering for companies.', 'Сайти й застосунки з текстової підказки
Вибір мовної моделі
Готові шаблони
Інтеграція з Supabase
Розгортання, завантаження й власний домен
Режим планування проєкту', 'Websites and apps from a text prompt
Choice of language model
Ready-made templates
Supabase integration
Deployment, download and custom domain
Project planning mode', 'Підприємці й початківці, які хочуть створити сайт чи застосунок без програмування.', 'Entrepreneurs and beginners who want to build a website or app without programming.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
