SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'wordrific.com' OR LOWER(`name`) = LOWER('Wordrific'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Wordrific', NULL, 'https://wordrific.com', NULL, NULL, 'AI-платформа контент-маркетингу для B2B: на основі дослідження ідеального клієнта пише SEO-статті вашим голосом і автоматично публікує їх на кількох каналах, щоб вас знаходили в Google та AI-пошуку.', 'An AI content marketing platform for B2B: based on ideal customer research it writes SEO articles in your voice and automatically publishes them across several channels so you are found in Google and AI search.', 'Wordrific допомагає B2B-компаніям і експертам системно будувати репутацію через контент. Платформа вивчає профіль вашого ідеального клієнта, підказує, про що варто писати, і готує статті, оптимізовані для пошуку в Google та в AI-сервісах на кшталт ChatGPT і Perplexity. AI навчається на вашій експертизі та стилі, тож тексти звучать вашим голосом. Готові матеріали автоматично публікуються на кількох каналах, а в кабінеті видно опубліковані й заплановані статті, SEO-оцінку та перегляди. Є безкоштовні інструменти й 7-денний пробний період з повним доступом до всіх функцій.', 'Wordrific helps B2B companies and experts build authority through content in a systematic way. The platform studies your ideal customer profile, suggests what to write about and prepares articles optimized for search in Google and in AI services such as ChatGPT and Perplexity. The AI learns from your expertise and style so the texts sound like you. Finished pieces are automatically published across several channels, and the dashboard shows published and scheduled articles, SEO scores and views. There are free tools and a 7-day trial with full access to every feature.', 'Теми статей на основі профілю ідеального клієнта
SEO-статті для Google та AI-пошуку
