-- Jason AI — Продажі
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'reply.io/jason-ai' OR LOWER(`name`) = LOWER('Jason AI'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Jason AI', NULL, 'https://reply.io/jason-ai', NULL, NULL, 'AI-агент з продажів від Reply.io: вивчає ваш продукт і стратегію, знаходить ідеальних клієнтів, персоналізує розсилки в кількох каналах, обробляє відповіді й записує на зустрічі.', 'An AI sales agent from Reply.io: it learns your product and strategy, finds ideal customers, personalizes multichannel outreach, handles replies and books meetings.', 'Jason AI виконує роботу менеджера з первинних продажів. Агент вивчає ваш продукт і стратегію продажів, шукає компанії й людей, що відповідають профілю ідеального клієнта, і запускає персоналізовані розсилки в кількох каналах. Він також обробляє відповіді потенційних клієнтів і домовляється про зустрічі, тож команді не потрібно розширювати штат, щоб охопити більше контактів. У мобільному застосунку можна переглядати вхідні, перевіряти й надсилати відповіді, згенеровані AI, отримувати сповіщення про відповіді та стежити за станом поштових скриньок і LinkedIn-акаунтів. Jason AI входить до платформи Reply.io, яка також має базу B2B-контактів, пошук email, збагачення даних і інструменти доставлюваності листів.', 'Jason AI does the work of a sales development rep. The agent learns your product and sales strategy, finds companies and people that match your ideal customer profile and launches personalized outreach across several channels. It also handles prospect replies and books meetings, so the team can reach more contacts without hiring. In the mobile app you can check the inbox, review and send AI-generated replies, get notified when a prospect responds and monitor the health of mailboxes and LinkedIn accounts. Jason AI is part of the Reply.io platform, which also offers a B2B contact database, email finders, data enrichment and deliverability tools.', 'Пошук ідеальних клієнтів
Персоналізовані розсилки в кількох каналах
Обробка відповідей і запис на зустрічі
Мобільний застосунок для перегляду й відповідей
Контроль стану поштових скриньок і LinkedIn
Інтеграція з платформою Reply.io', 'Finds ideal customers
Personalized multichannel outreach
Handles replies and books meetings
Mobile app for reviewing and replying
Mailbox and LinkedIn health monitoring
Part of the Reply.io platform', 'B2B-компанії та команди продажів, які хочуть масштабувати холодні розсилки без розширення штату.', 'B2B companies and sales teams that want to scale cold outreach without growing headcount.', 'web,mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
