INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Norton Neo', NULL, 'https://neobrowser.ai', NULL, NULL, 'Безкоштовний браузер від Norton з вбудованим AI, захистом від фішингу й шкідливих сайтів, блокуванням трекерів і реклами та вбудованим VPN — для Windows, Mac, Linux, iOS і Android.', 'A free browser from Norton with built-in AI, protection against phishing and malicious sites, tracker and ad blocking and a built-in VPN, for Windows, Mac, Linux, iOS and Android.', 'Norton Neo — браузер, який поєднує звичний пошук, генеративний AI і захист, побудований на технологіях Norton. Він виявляє й блокує фішинг, шкідливі програми та підроблені інтернет-магазини ще до того, як вони відкриються, і працює одразу після встановлення без налаштувань. Вбудовані блокування трекерів і реклами, VPN, у тому числі для стримінгу, та приватний AI-помічник. Браузер безкоштовний і доступний для Windows, Mac, Linux, iOS та Android.', 'Norton Neo is a browser that combines familiar search, generative AI and protection built on Norton technology. It detects and blocks phishing, malware and fake online shops before they open, and works right after installation with no setup. Tracker and ad blocking, a VPN including for streaming, and a private AI assistant are built in. The browser is free and available for Windows, Mac, Linux, iOS and Android.', 'Вбудований приватний AI-помічник
