-- EchoWrite — Транскрипція
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'echo-write.com' OR LOWER(`name`) = LOWER('EchoWrite'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'EchoWrite', NULL, 'https://echo-write.com', NULL, NULL, 'Настільний застосунок для голосового набору в Windows і macOS: перетворює мовлення на охайний текст у будь-якій програмі, прибирає слова-паразити, перекладає на льоту й переформатовує текст за вашими голосовими командами.', 'A desktop voice typing app for Windows and macOS: it turns speech into clean text in any app, removes filler words, translates on the fly and reformats text with your voice commands.', 'EchoWrite дозволяє диктувати замість того, щоб друкувати, — і працює в будь-якій програмі, де є курсор: у месенджерах, Notion, редакторах коду чи браузері. Розпізнавання мовлення побудоване на моделі OpenAI Whisper. Застосунок автоматично прибирає «е-е», повтори й обмовки, тож на виході виходить готовий до використання текст. Можна говорити однією мовою, а отримувати текст іншою: переклад відбувається в реальному часі, а мову можна змінювати навіть посеред речення — вона визначається автоматично. Окремі голосові команди та власні підказки дозволяють одразу перетворити довгий потік думок на структуроване завдання, документ у Markdown чи стислий підсумок, або змінити стиль тексту. Застосунок нативний для Windows 10/11 і macOS; на сайті зазначено, що дані користувача не збираються.', 'EchoWrite lets you dictate instead of typing, in any app that has a cursor: messengers, Notion, code editors or the browser. Speech recognition is built on the OpenAI Whisper model. The app automatically removes filler sounds, repetitions and slips, so the output is ready-to-use text. You can speak one language and get text in another: translation happens in real time, and the language can change even mid-sentence because it is detected automatically. Voice commands and custom prompts let you turn a long stream of thoughts into a structured task, a Markdown document or a short summary, or change the style of the text. The app is native for Windows 10/11 and macOS; the site states that no user data is collected.', 'Голосовий набір у будь-якій програмі
Розпізнавання на основі OpenAI Whisper
Автоматичне прибирання слів-паразитів і обмовок
Переклад мовлення в реальному часі
Автовизначення мови, зміна мови посеред речення
Голосові команди й власні підказки для форматування
Нативні застосунки для Windows і macOS', 'Voice typing in any app
Recognition based on OpenAI Whisper
Automatic removal of filler words and slips
Real-time speech translation
Automatic language detection, switch mid-sentence
Voice commands and custom prompts for formatting
Native apps for Windows and macOS', 'Люди, які багато пишуть — розробники, менеджери, автори — і хочуть диктувати замість набору тексту.', 'People who write a lot (developers, managers, writers) and want to dictate instead of typing.', 'desktop', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
