INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'EchoWrite lets you dictate instead of typing, in any app that has a cursor: messengers, Notion, code editors or the browser. Speech recognition is built on the OpenAI Whisper model. The app automatically removes filler sounds, repetitions and slips, so the output is ready-to-use text. You can speak one language and get text in another: translation happens in real time, and the language can change even mid-sentence because it is detected automatically. Voice commands and custom prompts let you turn a long stream of thoughts into a structured task, a Markdown document or a short summary, or change the style of the text. The app is native for Windows 10/11 and macOS; the site states that no user data is collected.', 'manual' FROM DUAL WHERE @new = 1;
