-- Format Magic — Документи
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'formatmagic.ai' OR LOWER(`name`) = LOWER('Format Magic'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Format Magic', NULL, 'https://formatmagic.ai', NULL, NULL, 'AI-форматувальник документів: перетворює неоформлений текст, нотатки, листи чи відповіді ChatGPT на охайні пропозиції, звіти й резюме за готовими шаблонами приблизно за хвилину.', 'An AI document formatter: it turns unformatted text, notes, emails or ChatGPT replies into tidy proposals, reports and résumés using ready-made templates in about a minute.', 'Format Magic економить час на ручному оформленні документів у Word. Ви обираєте шаблон, вставляєте свій текст — з нотаток, листа, будь-якого простого редактора чи відповіді ChatGPT, Gemini або іншого AI — і отримуєте структурований документ із професійною версткою, готовий до друку. Сервіс підходить для бізнес-пропозицій, звітів для клієнтів, матеріалів консультантів і резюме. Спробувати можна без реєстрації; для регулярної роботи є підписка.', 'Format Magic saves time on manual document formatting in Word. You choose a template, paste your text from notes, an email, any plain editor or a reply from ChatGPT, Gemini or another AI, and get a structured, professionally laid-out document ready for print. It suits business proposals, client reports, consultant deliverables and résumés. You can try it without signing up; a subscription is available for regular use.', 'Форматування простого тексту за шаблоном
Оформлення відповідей ChatGPT та інших AI
Пропозиції, звіти, резюме
Документ, готовий до друку
Спроба без реєстрації', 'Formatting plain text with a template
Formatting ChatGPT and other AI output
Proposals, reports, résumés
Print-ready documents
Try without signing up', 'Консультанти, фрилансери й малий бізнес, які регулярно готують документи для клієнтів.', 'Consultants, freelancers and small businesses that regularly prepare documents for clients.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
