-- MOVA Guide — Подорожі
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'movaguide.com' OR LOWER(`name`) = LOWER('MOVA Guide'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'MOVA Guide', NULL, 'https://movaguide.com', NULL, NULL, 'AI-гід містом: скажіть, у якому ви настрої, скільки маєте часу й який бюджет, — і отримаєте один готовий план з ресторанами, подіями, природою чи нічним життям поруч.', 'An AI city guide: tell it your mood, how much time you have and your budget, and get one ready plan with restaurants, events, nature or nightlife nearby.', 'MOVA Guide зменшує час на пошуки, чим зайнятися. Ви обираєте місто, дату, скільки маєте часу — від пів години до цілого дня — і бюджет, а також настрій: їжа, культура, природа, відпочинок, шопінг, події, нові заклади, нічне життя, розваги чи екскурсії. Можна попросити персональну добірку, класичні місця, які варто побачити, або улюблені місця місцевих. Сервіс складає один план, що вкладається у ваш час і бюджет, а для компанії друзів є груповий план. Окремо доступна розсилка з новими гідами й історіями районів. Для повного доступу потрібна реєстрація.', 'MOVA Guide cuts the time spent searching for something to do. You choose a city, a date, how much time you have, from half an hour to a whole day, and a budget, plus a mood: food, culture, nature, relaxing, shopping, events, new openings, nightlife, entertainment or tours. You can ask for a personal pick, the classic must-sees or places locals love. The service builds one plan that fits your time and budget, and there is a group plan for going out with friends. A newsletter with new guides and neighborhood stories is also available. Full access requires signing up.', 'План на день за настроєм, часом і бюджетом
Ресторани, події, культура, природа, нічне життя
Добірки класики й місць від місцевих
Групові плани з друзями
Розсилка з міськими гідами', 'A day plan by mood, time and budget
Restaurants, events, culture, nature, nightlife
Classic sights and local favorites
Group plans with friends
Newsletter with city guides', 'Місцеві жителі й туристи, які хочуть швидко вирішити, куди піти.', 'Locals and tourists who want to decide quickly where to go.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
