-- Hashvix AI — Музика
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'hashvix.com' OR LOWER(`name`) = LOWER('Hashvix AI'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Hashvix AI', NULL, 'https://hashvix.com', NULL, NULL, 'AI-студія музики й відео: перетворює ідею, повідомлення, текст пісні чи історію на завершену пісню з вокалом і бітом, а потім — на короткий вертикальний кліп для TikTok, Reels і Shorts.', 'An AI music and video studio: it turns an idea, message, lyrics or story into a finished song with vocals and beat, and then into a short vertical video for TikTok, Reels and Shorts.', 'Hashvix AI створює повноцінні пісні з будь-якої ідеї. Достатньо дати підказку, повідомлення, власний текст пісні чи коротку історію — сервіс разом згенерує слова, вокал, біт і зведений трек. Кожну пісню можна одразу перетворити на коротке вертикальне музичне відео, готове до публікації в TikTok, Instagram Reels чи YouTube Shorts. Серед додаткових можливостей — ремікси, подовження треку, окремі доріжки (стеми) і MIDI для подальшої роботи. Створені пісні можна публікувати в загальній стрічці сервісу. За даними сайту, треки мають комерційні права без роялті для стримінгових платформ і YouTube. Безкоштовний тариф дає невелику кількість кредитів на місяць; платні додають генератор кліпів, пріоритетну обробку, необмежені завантаження й якісне аудіо.', 'Hashvix AI creates complete songs from any idea. Give it a prompt, a message, your own lyrics or a short story, and the service generates the lyrics, vocals, beat and mixed track together. Each song can immediately become a short vertical music video ready for TikTok, Instagram Reels or YouTube Shorts. Extra features include remixes, track extension, separate stems and MIDI for further work. Finished songs can be shared in the service''s public feed. According to the site, tracks come with royalty-free commercial rights for streaming platforms and YouTube. The free plan gives a small number of credits per month; paid plans add the music video generator, priority processing, unlimited downloads and high-quality audio.', 'Пісня з ідеї, тексту чи історії
Генерація слів, вокалу й біту разом
Вертикальні музичні кліпи для соцмереж
Ремікси й подовження треків
Стеми й MIDI
Комерційні права на треки', 'A song from an idea, lyrics or story
Lyrics, vocals and beat generated together
Vertical music videos for social media
Remixes and track extension
Stems and MIDI
Commercial rights for tracks', 'Автори контенту й музиканти-початківці, яким потрібні пісні та кліпи для соцмереж.', 'Content creators and beginner musicians who need songs and videos for social media.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
