SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'whacka.app' OR LOWER(`name`) = LOWER('Whacka'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Whacka', NULL, 'https://whacka.app', NULL, NULL, 'No-code конструктор застосунків: опишіть застосунок одним реченням — Whacka напише його, розмістить і опублікує за кілька хвилин, з входом користувачів, базою даних, оплатами й сповіщеннями.', 'A no-code app builder: describe your app in one sentence and Whacka writes, hosts and publishes it within minutes, with user sign-in, a database, payments and notifications.', 'Whacka дозволяє створити робочий застосунок чи гру без коду, команди й досвіду. Ви описуєте, що потрібно, звичайними словами, і сервіс сам пише застосунок, розміщує його та запускає. Усі можливості додаються простим проханням у чаті: бронювання, оплати, учасники й команди, push-сповіщення, вбудований AI, завантаження файлів і нагадування за розкладом. Хостинг, база даних і AI уже працюють, тож не потрібні ключі, сервери чи налаштування. Застосунок має власну адресу, встановлюється на головний екран, працює на комп''ютерах і телефонах, а тепер його можна відправити й у магазини застосунків. Нічого не публікується без вашого підтвердження, кожна версія зберігається з можливістю повернутися. Застосунок також звітує, хто зареєструвався і що потребує уваги. Є безкоштовний старт, тижнева та місячна підписка; витрати на AI ваших користувачів сплачують вони самі.', 'Whacka lets you build a working app or game with no code, team or experience. You describe what you need in plain words, and the service writes the app, hosts it and launches it. Every capability is added simply by asking in the chat: bookings, payments, members and teams, push notifications, built-in AI, file uploads and scheduled reminders. Hosting, a database and AI are already running, so there are no keys, servers or setup. The app gets its own address, installs on the home screen, works on computers and phones, and can now be shipped to app stores too. Nothing goes live without your confirmation, and every version is saved so you can roll back. The app also reports who signed up and what needs your attention. There is a free start plus weekly and monthly plans; your users pay their own AI costs.', 'Застосунок з одного речення без коду
Вхід користувачів, база даних і сховище
Оплати, бронювання, команди й сповіщення
