-- SureThing — AI-агенти
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'surething.io' OR LOWER(`name`) = LOWER('SureThing'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'SureThing', NULL, 'https://surething.io', NULL, NULL, 'Команда AI-агентів для малого бізнесу: веде соцмережі, перетворює фото товару на готові пости й відео, допомагає з сайтом і рекламою, а перед незворотними діями просить підтвердження.', 'A team of AI agents for small businesses: it runs social media, turns a product photo into ready posts and videos, helps with the website and ads, and asks for approval before irreversible actions.', 'SureThing — це не чат-бот, а набір агентів, які виконують конкретну роботу для малого бізнесу. Замість порожнього чату ви обираєте готове рішення з бібліотеки агентів, яке вже знає потрібний процес: агент підключається до ваших сервісів, створює результат і просить підтвердження перед будь-якою незворотною дією. Наприклад, одна ідея перетворюється на п''ять дописів у форматах різних соцмереж, а одне фото товару — на готовий постер і коротке відео. Також сервіс допомагає створювати й покращувати сайт і запускати рекламу; аудит сайту за кількома показниками позначено як майбутню функцію. Агенти мають спільну пам''ять, тож не працюють ізольовано, а налаштування займає кілька хвилин. Є щоденні брифінги й нагадування та настільний застосунок. Тарифи працюють на кредитах; якщо AI помиляється, частину кредитів повертають.', 'SureThing is not a chatbot but a set of agents that do concrete work for small businesses. Instead of a blank chat you pick a ready solution from the agent library that already knows the workflow: the agent connects to your services, creates the deliverable and asks for approval before any irreversible step. For example, one idea becomes five posts in the native formats of different social networks, and one product photo becomes a ready poster and a short video. The service also helps build and improve your website and launch ads; a multi-factor website audit is marked as coming soon. The agents share memory, so they do not work in silos, and setup takes a few minutes. There are daily briefings and reminders and a desktop app. Plans run on credits; some credits are returned when the AI gets something wrong.', 'Бібліотека готових агентів під бізнес-процеси
Одна ідея — дописи для п''яти соцмереж
Постер і відео з одного фото товару
Допомога із сайтом і запуском реклами
Підтвердження перед незворотними діями
Спільна пам''ять агентів
Щоденні брифінги й нагадування', 'Library of ready agents for business workflows
One idea into posts for five social networks
Poster and video from one product photo
Help with the website and launching ads
Approval before irreversible actions
Shared memory across agents
Daily briefings and reminders', 'Власники малого бізнесу, які хочуть делегувати маркетинг і рутинні завдання AI-агентам.', 'Small business owners who want to hand marketing and routine tasks to AI agents.', 'web,desktop', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
