-- AI Aware — Детектори
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'aiaware.io' OR LOWER(`name`) = LOWER('AI Aware'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'AI Aware', NULL, 'https://aiaware.io', NULL, NULL, 'Платформа виявлення AI-контенту: перевіряє, чи текст написаний мовною моделлю, і розпізнає дипфейк-відео, згенеровані зображення та клоновані голоси — з оцінкою впевненості й поясненням.', 'An AI content detection platform: it checks whether text was written by a language model and detects deepfake videos, generated images and cloned voices, with a confidence score and explanation.', 'AI Aware поєднує в одній платформі чотири типи перевірок на штучно створений контент. Детектор тексту аналізує стиль письма, структуру речень і статистичні ознаки, характерні для текстів від ChatGPT, Claude, Gemini, Grok та інших моделей, і видає не просто «так/ні», а оцінку впевненості з поясненням. Його застосовують для перевірки академічної доброчесності, юридичних документів, редакторського контролю, відбору кандидатів і аудиту маркетингового контенту. Детектор дипфейк-відео шукає неприродні риси облич, моргання, артефакти освітлення та аномалії між кадрами. Також платформа перевіряє зображення на ознаки генерації та аудіо на клонування голосу. Сервіс орієнтований на захист репутації брендів і безпеку; доступна безкоштовна пробна версія.', 'AI Aware combines four types of checks for artificially created content on one platform. The text detector analyzes writing style, sentence structure and statistical traits typical of text from ChatGPT, Claude, Gemini, Grok and other models, and returns not just a yes or no but a confidence score with an explanation. It is used for academic integrity checks, legal document review, editorial quality control, recruitment screening and marketing content audits. The deepfake video detector looks for unnatural facial features, blinking, lighting artifacts and anomalies between frames. The platform also checks images for signs of generation and audio for voice cloning. The service focuses on brand reputation and security; a free trial is available.', 'Виявлення тексту, написаного AI
Розпізнавання дипфейк-відео
Перевірка зображень на генерацію
Виявлення клонованих голосів
Оцінка впевненості з поясненням', 'Detection of AI-written text
Deepfake video detection
Checks images for generation
Cloned voice detection
Confidence score with explanation', 'Навчальні заклади, редакції, юристи, HR-фахівці та бренди, яким потрібно перевіряти автентичність контенту.', 'Schools, newsrooms, lawyers, HR specialists and brands that need to verify content authenticity.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
