INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'AI Aware combines four types of checks for artificially created content on one platform. The text detector analyzes writing style, sentence structure and statistical traits typical of text from ChatGPT, Claude, Gemini, Grok and other models, and returns not just a yes or no but a confidence score with an explanation. It is used for academic integrity checks, legal document review, editorial quality control, recruitment screening and marketing content audits. The deepfake video detector looks for unnatural facial features, blinking, lighting artifacts and anomalies between frames. The platform also checks images for signs of generation and audio for voice cloning. The service focuses on brand reputation and security; a free trial is available.', 'manual' FROM DUAL WHERE @new = 1;
