-- PrompTessor — Генератори промптів
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'promptessor.com' OR LOWER(`name`) = LOWER('PrompTessor'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'PrompTessor', NULL, 'https://promptessor.com', NULL, NULL, 'Робочий простір для AI-промптів: генерує, аналізує, оптимізує й уточнює підказки для ChatGPT, Claude, Gemini та інших моделей, відновлює промпт з готового зображення чи тексту й зберігає вдалі в бібліотеці.', 'A workspace for AI prompts: it generates, analyzes, optimizes and refines prompts for ChatGPT, Claude, Gemini and other models, reconstructs a prompt from a finished image or text and saves useful ones in a library.', 'PrompTessor допомагає отримувати якісніші результати від AI без переходу на дорожчу модель — за рахунок якісніших підказок. Генератор створює професійні промпти під будь-яку мету й формат. Аналіз показує, що в підказці працює, а що варто покращити. Оптимізатор перетворює чорновий запит на сильнішу версію, а режим уточнення дозволяє поступово доводити наявні промпти з урахуванням зворотного зв''язку й параметрів форматування. Окрема функція відновлює промпт із готового зображення, відео, сторінки чи тексту, щоб його можна було повторно використати й адаптувати. Вдалі підказки зберігаються й упорядковуються в бібліотеці. Сервіс працює з ChatGPT, Claude, Gemini та іншими моделями, має мобільний застосунок, а розширення для Chrome позначено як «скоро». Почати можна безкоштовно.', 'PrompTessor helps you get higher-quality results from AI without moving to a more expensive model, by writing better prompts. The generator creates professional prompts for any goal and format. Analysis shows what works in a prompt and what to improve. The optimizer turns a rough request into a stronger version, and refinement mode lets you gradually improve existing prompts with feedback and formatting options. A separate feature reconstructs a prompt from a finished image, video, page or text so you can reuse and adapt it. Useful prompts are saved and organized in a library. The service works with ChatGPT, Claude, Gemini and other models, has a mobile app, and a Chrome extension is marked as coming soon. You can start for free.', 'Генерація промптів під будь-яку мету
Аналіз сильних і слабких місць підказки
Оптимізація й поступове уточнення промптів
Відновлення промпту з зображення, відео чи тексту
Бібліотека збережених промптів
Робота з ChatGPT, Claude, Gemini', 'Prompt generation for any goal
Analysis of a prompt''s strengths and weaknesses
Prompt optimization and step-by-step refinement
Reconstructing a prompt from an image, video or text
Library of saved prompts
Works with ChatGPT, Claude, Gemini', 'Автори контенту, маркетологи, розробники й усі, хто регулярно працює з AI-моделями.', 'Content creators, marketers, developers and anyone who works with AI models regularly.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
