SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'kikivoice.ai' OR LOWER(`name`) = LOWER('KikiVoice'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'KikiVoice', NULL, 'https://kikivoice.ai', NULL, NULL, 'Онлайн-сервіс клонування голосу й озвучення тексту: записуєте чи завантажуєте зразок свого голосу й за кілька хвилин отримуєте його цифрову копію з підтримкою понад 75 мов, емоцій і акцентів.', 'An online voice cloning and text-to-speech service: record or upload a sample of your voice and within minutes get a digital copy that supports 75+ languages, emotions and accents.', 'KikiVoice дозволяє створити копію власного голосу без реєстрації та картки. Достатньо записати голос у браузері або завантажити аудіофайл, ввести текст і запустити клонування — результат готовий за кілька хвилин. Доступні три вбудовані моделі клонування, понад 75 мов, а також керування емоціями й акцентом. Крім клонування, сервіс пропонує створення нового голосу за описом, озвучення тексту та зміну голосу. Інтерфейс доступний кількома мовами. Клонувати слід лише власний голос або голос людини, яка дала на це згоду.', 'KikiVoice lets you create a copy of your own voice with no sign-up or card. Record your voice in the browser or upload an audio file, enter text and start cloning; the result is ready in a few minutes. Three built-in cloning models, more than 75 languages and control over emotion and accent are available. Besides cloning, the service offers creating a new voice from a description, text-to-speech and a voice changer. The interface is available in several languages. Only clone your own voice or the voice of someone who has given consent.', 'Клонування голосу за кілька хвилин
Запис у браузері або завантаження файлу
Понад 75 мов
Керування емоціями й акцентом
Створення голосу за описом
Озвучення тексту й зміна голосу
Без реєстрації', 'Voice cloning in a few minutes
Record in the browser or upload a file
75+ languages
Emotion and accent control
Create a voice from a description
Text-to-speech and voice changer
No sign-up', 'Автори контенту, які хочуть озвучувати відео власним голосом різними мовами.', 'Content creators who want to voice videos with their own voice in different languages.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
