SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'vidnix.ai' OR LOWER(`name`) = LOWER('Vidnix'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Vidnix', NULL, 'https://vidnix.ai', NULL, NULL, 'AI-генератор відео, що об''єднує кілька сторонніх моделей в одному робочому просторі: відео з тексту, сценарію, зображення чи іншого відео, AI-ефекти й генерація зображень.', 'An AI video generator that brings several third-party models into one workspace: video from text, a script, an image or another video, AI effects and image generation.', 'Vidnix дає доступ до кількох моделей генерації відео різних розробників в одному інтерфейсі, тож не потрібно перемикатися між сервісами. Почати можна з текстового опису, сценарію, зображення товару чи наявного відео: доступні режими «текст у відео», «зображення у відео», «відео у відео», набір готових AI-ефектів і генерація зображень. Сервіс підходить для відео в соцмережі, демонстрацій продуктів, реклами, кінематографічних сцен і пояснювальних роликів. Оплата відбувається кредитами; якщо генерація не вдалася, кредити повертаються. Нові користувачі можуть отримати стартові безкоштовні кредити.', 'Vidnix gives access to several video generation models from different developers in one interface, so you do not have to switch between services. You can start from a text description, a script, a product image or an existing video: text-to-video, image-to-video and video-to-video modes, a set of ready AI effects and image generation are available. It suits social media videos, product demos, ads, cinematic scenes and explainers. You pay with credits; if a generation fails, the credits are returned. New users can get free starter credits.', 'Кілька моделей генерації відео в одному сервісі
Відео з тексту, сценарію чи зображення
Режим «відео у відео»
Готові AI-ефекти
Генерація зображень
Повернення кредитів за невдалу генерацію', 'Several video generation models in one service
Video from text, a script or an image
Video-to-video mode
Ready-made AI effects
Image generation
Credits returned for failed generations', 'Автори контенту, маркетологи й бізнес, яким потрібні короткі відео без зйомок.', 'Content creators, marketers and businesses that need short videos without filming.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
