SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'vidflux.ai' OR LOWER(`name`) = LOWER('VidFlux'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'VidFlux', NULL, 'https://vidflux.ai', NULL, NULL, 'AI-генератор відео з тексту чи зображення на основі популярних сторонніх моделей, із режимом перенесення рухів з референсного відео на будь-якого персонажа за фото.', 'An AI video generator from text or an image based on popular third-party models, with a mode that transfers motion from a reference video to any character in a photo.', 'VidFlux перетворює текстовий опис або завантажене фото на готове відео у форматі MP4 приблизно за хвилину. Можна обрати одну з кількох моделей генерації та співвідношення сторін; у режимі «зображення у відео» статичне фото оживає, а відео може мати звук. Окремий режим «відео у відео» переносить рухи з короткого референсного ролика на персонажа з вашого фото, зберігаючи його зовнішність, жести й міміку. Сервіс підходить для соцмереж, маркетингу та творчого контенту. Усі тарифи дають доступ до всіх моделей, відео без водяного знака й комерційні права; невикористані кредити переносяться на наступний місяць.', 'VidFlux turns a text description or an uploaded photo into a finished MP4 video in about a minute. You can choose one of several generation models and the aspect ratio; in image-to-video mode a still photo comes to life, and the video can include sound. A separate video-to-video mode transfers the motion from a short reference clip to the character in your photo, keeping their appearance, gestures and facial expressions. It suits social media, marketing and creative content. All plans include every model, videos without a watermark and commercial rights; unused credits roll over to the next month.', 'Відео з тексту чи фото
Вибір моделі генерації
Перенесення рухів з референсного відео
Відео зі звуком
Без водяного знака, комерційні права
Перенесення невикористаних кредитів', 'Video from text or a photo
Choice of generation model
Motion transfer from a reference video
Video with sound
No watermark, commercial rights
Unused credits roll over', 'Автори контенту для соцмереж і маркетологи.', 'Social media content creators and marketers.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
