-- HappySeeds — Конструктори сайтів
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'happyseeds.ai' OR LOWER(`name`) = LOWER('HappySeeds'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'HappySeeds', NULL, 'https://happyseeds.ai', NULL, NULL, 'AI-платформа для малого бізнесу: у розмові з AI-агентами створює сайт, магазин, вебзастосунок чи гру, а також маркетингові відео — без розробників і монтажерів.', 'An AI platform for small businesses: in a chat with AI agents it creates a website, shop, web app or game, plus marketing videos, with no developers or video editors.', 'HappySeeds дозволяє запустити й просувати бізнес через звичайний чат. AI-агенти створюють сайт, що надає бізнесу солідного вигляду — з послугами, цінами й контактами, — інтернет-магазин, гру чи робочий інструмент, наприклад для розкладу змін, чергувань або заявок. На сайт можна додати живий календар, де клієнти самі обирають час, SEO-заголовки й метадані генеруються автоматично, а проєкт можна запустити на власному домені. Для старту є готові шаблони. Окремий напрям — відео й матеріали бренду: можна взяти відео-референс і відтворити його структуру з власними персонажами та стилем або зробити нову сцену з одного фото товару. Для роботи можна обрати одну з кількох мовних моделей. Оплата відбувається кредитами за підпискою, почати можна безкоштовно.', 'HappySeeds lets you launch and promote a business through a simple chat. AI agents create a website that makes the business look established, with services, prices and contacts, an online shop, a game or a working tool, for example for shift schedules, rotations or tickets. You can add a live calendar where customers pick a time themselves, SEO titles and metadata are generated automatically, and the project can go live on your own domain. Ready templates help you start. A separate area covers video and brand assets: take a reference video and recreate its structure with your own characters and style, or create a new scene from a single product photo. You can choose one of several language models to work with. Payment is by subscription credits, and you can start for free.', 'Сайти, магазини, вебзастосунки й ігри через чат
Онлайн-запис клієнтів через календар на сайті
Автоматичні SEO-заголовки й метадані
Власний домен і готові шаблони
Відтворення відео за референсом
Відео з одного фото товару', 'Websites, shops, web apps and games through chat
Online booking via a calendar on the site
Automatic SEO titles and metadata
Custom domain and ready templates
Recreating videos from a reference
Video from a single product photo', 'Власники малого бізнесу, яким потрібні сайт чи застосунок і рекламні відео без найму фахівців.', 'Small business owners who need a website or app and ad videos without hiring specialists.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
