SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'mojomake.com' OR LOWER(`name`) = LOWER('MojoMake'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'MojoMake', NULL, 'https://mojomake.com', NULL, NULL, 'Платформа для створення відео й зображень, що об''єднує понад десять популярних AI-моделей однією підпискою: відео з тексту чи фото, ефекти, розширення кадру, видалення фону.', 'A platform for creating video and images that brings together more than ten popular AI models in one subscription: video from text or photos, effects, frame extension and background removal.', 'MojoMake збирає в одному кабінеті популярні моделі генерації відео та зображень від різних розробників, щоб не тримати окремі акаунти й підписки на кожну. Моделі перемикаються одним кліком. Доступні відео з тексту, з зображення чи з референсу, генерація за першим і останнім кадром, перенесення рухів, відео- й фотоефекти, подовження відео, створення й редагування зображень, розширення кадру та видалення фону; є понад сто шаблонів та ефектів. Відео експортуються у 1080p, зображення — у 4K, без водяних знаків, із комерційними правами на використання в рекламі та на YouTube. Тарифи працюють на кредитах і відрізняються кількістю одночасних завдань і швидкістю; почати можна безкоштовно без картки, є також разові пакети кредитів.', 'MojoMake gathers popular video and image generation models from different developers in one dashboard, so you do not need separate accounts and subscriptions for each. Models switch with one click. Available features include video from text, from an image or from a reference, generation by first and last frame, motion transfer, video and photo effects, video extension, image creation and editing, frame extension and background removal; there are more than a hundred templates and effects. Videos export in 1080p and images in 4K, without watermarks, with commercial rights for ads and YouTube. Plans run on credits and differ in concurrent tasks and speed; you can start for free with no card, and one-time credit packs are also available.', 'Понад 10 моделей генерації в одному кабінеті
Відео з тексту, фото чи референсу
Перенесення рухів і подовження відео
Генерація та редагування зображень
Видалення фону й розширення кадру
Експорт 1080p/4K без водяних знаків
Комерційні права', '10+ generation models in one dashboard
Video from text, a photo or a reference
Motion transfer and video extension
Image generation and editing
Background removal and frame extension
1080p/4K export without watermarks
Commercial rights', 'Автори контенту й бізнес, яким потрібні різні генеративні моделі для відео та зображень за однією підпискою.', 'Content creators and businesses that need various generative models for video and images in one subscription.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
