-- Make-It — Рукоділля
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'make-it.ai' OR LOWER(`name`) = LOWER('Make-It'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Make-It', NULL, 'https://make-it.ai', NULL, NULL, 'AI-платформа для саморобної електроніки: опишіть ідею пристрою звичайною мовою — і отримаєте схему, перелік компонентів, код для мікроконтролера та покрокову інструкцію складання.', 'An AI platform for DIY electronics: describe a device idea in plain language and get a schematic, a parts list, microcontroller code and step-by-step build instructions.', 'Make-It допомагає перетворити ідею на справжній фізичний пристрій навіть без навичок програмування. Ви описуєте звичайними словами, що хочете зробити, а сервіс готує схеми, список компонентів для покупки, код та інструкції. Далі залишається зібрати пристрій за інструкцією і записати код на плату одним кліком, після чого можна вдосконалювати проєкт. Платформа орієнтована на популярні плати на кшталт Arduino та Raspberry Pi. Ідея сервісу — зробити корисний гаджет значно дешевше за готовий: код працює безпосередньо на чипі, без залежності від хмари, пристрій спілкується лише з вами, а відкриті стандарти дозволяють користуватися ним без обмежень у часі.', 'Make-It helps turn an idea into a real physical device even without programming skills. You describe in plain words what you want to make, and the service prepares diagrams, a shopping list of components, code and instructions. Then you build the device by following the instructions and flash the code to the board with one click, after which you can keep improving the project. The platform focuses on popular boards such as Arduino and Raspberry Pi. The idea is to make a useful gadget much cheaper than a ready-made one: the code runs directly on the chip without depending on the cloud, the device talks only to you, and open standards let you use it indefinitely.', 'Проєкт пристрою з опису звичайною мовою
Схеми та перелік компонентів
Готовий код для мікроконтролера
Покрокові інструкції складання
Запис коду на плату одним кліком
Робота без хмари', 'Device project from a plain-language description
Diagrams and parts list
Ready microcontroller code
Step-by-step build instructions
One-click code flashing
Works without the cloud', 'Аматори електроніки, мейкери й усі, хто хоче зібрати власний гаджет на Arduino чи Raspberry Pi.', 'Electronics hobbyists, makers and anyone who wants to build their own gadget on Arduino or Raspberry Pi.', 'web', 'basic', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
