INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Make-It helps turn an idea into a real physical device even without programming skills. You describe in plain words what you want to make, and the service prepares diagrams, a shopping list of components, code and instructions. Then you build the device by following the instructions and flash the code to the board with one click, after which you can keep improving the project. The platform focuses on popular boards such as Arduino and Raspberry Pi. The idea is to make a useful gadget much cheaper than a ready-made one: the code runs directly on the chip without depending on the cloud, the device talks only to you, and open standards let you use it indefinitely.', 'manual' FROM DUAL WHERE @new = 1;
