SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'websitepublisher.ai' OR LOWER(`name`) = LOWER('WebsitePublisher.ai'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'WebsitePublisher.ai', NULL, 'https://websitepublisher.ai', NULL, NULL, 'Платформа, що публікує сайти, застосунки й магазини, створені в розмові з ChatGPT, Claude чи Mistral: з авторизацією, оплатами, формами, поштою, 124 інтеграціями та пам''яттю про проєкт.', 'A platform that publishes websites, apps and stores created in a conversation with ChatGPT, Claude or Mistral, with auth, payments, forms, email, 124 integrations and project memory.', 'WebsitePublisher.ai розв''язує проблему, з якою стикаються ті, хто створює сайти з AI-асистентами: код є, але де його розмістити, куди підуть заявки з форм, як приймати оплату і як змінити ціни наступного місяця без перегенерації всього. Ви описуєте сайт, застосунок, магазин, портфоліо чи блог будь-якому підтримуваному AI-асистенту — ChatGPT, Claude чи Mistral — і просите розмістити його на платформі. Проєкт одразу запускається на реальній адресі й продовжує працювати: зберігає дані, приймає форми й оплати, надсилає листи, приймає завантаження файлів. Доступні 124 інтеграції, візуальний редактор і пам''ять, завдяки якій AI пам''ятає проєкт і через місяці. Прив''язки до платформи немає. Для тих, хто ще не користується AI, є безкоштовний AI-коуч. Безкоштовний тариф дає один проєкт на піддомені; платні додають сторінки, власний домен, пошту на домені й SEO-налаштування.', 'WebsitePublisher.ai solves the problem people face when building websites with AI assistants: the code exists, but where does it live, where do form submissions go, how do you take payments and how do you change prices next month without regenerating everything? You describe a website, app, store, portfolio or blog to any supported AI assistant, ChatGPT, Claude or Mistral, and ask it to build on the platform. The project goes live at a real address right away and keeps working: it stores data, accepts forms and payments, sends emails and accepts file uploads. There are 124 integrations, a visual editor and memory, so the AI remembers the project even months later. There is no lock-in. For people not yet using AI there is a free AI coach. The free plan gives one project on a subdomain; paid plans add pages, a custom domain, email on your domain and SEO settings.', 'Публікація сайтів з ChatGPT, Claude і Mistral
Авторизація, оплати, форми й пошта
124 вбудовані інтеграції
Візуальний редактор
Пам''ять AI про проєкт
Без прив''язки до платформи
Власний домен на платних тарифах', 'Publishing websites from ChatGPT, Claude and Mistral
Auth, payments, forms and email
124 built-in integrations
Visual editor
AI memory of the project
No platform lock-in
Custom domain on paid plans', 'Люди, які створюють сайти й застосунки з AI-асистентами та хочуть швидко їх опублікувати й підтримувати.', 'People who build websites and apps with AI assistants and want to publish and maintain them quickly.', 'web,desktop', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
