-- VoooAI — Генерація відео
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'voooai.com' OR LOWER(`name`) = LOWER('VoooAI'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'VoooAI', NULL, 'https://voooai.com', NULL, NULL, 'AI-генератор відео й коротких серіалів: з одного речення створює сценарій, розкадровку та відео на візуальному полотні, використовуючи понад 25 сторонніх моделей.', 'An AI generator of videos and short series: from one sentence it creates a script, storyboard and video on a visual canvas using more than 25 third-party models.', 'VoooAI допомагає створювати короткі фільми, мінісеріали й рекламні ролики, починаючи з одного речення. Сервіс проводить увесь процес на одному візуальному полотні: пише сценарій, робить розкадровку й генерує відео, а також зображення й аудіо. Є два режими: режіссерський — з редагуванням розкадровки й експортом в один клік — і вільний редактор полотна, де процес складається з блоків перетягуванням. Під капотом — понад 25 моделей генерації від різних розробників; сервіс розуміє складні підказки й сам їх покращує. Доступні готові шаблони процесів. Безкоштовна версія дає щотижневі кредити, базові моделі й водяні знаки на зображеннях; платні тарифи відкривають усі моделі, вищу роздільну здатність, комерційну ліцензію й доступ через API.', 'VoooAI helps create short films, mini-series and ad videos starting from a single sentence. The service runs the whole process on one visual canvas: it writes the script, makes the storyboard and generates the video, as well as images and audio. There are two modes: a director mode with storyboard editing and one-click export, and a free canvas editor where the workflow is assembled from blocks by drag and drop. Under the hood are more than 25 generation models from different developers; the service understands complex prompts and improves them itself. Ready workflow templates are available. The free version gives weekly credits, basic models and watermarks on images; paid plans unlock all models, higher resolution, a commercial license and API access.', 'Від одного речення до сценарію, розкадровки й відео
Режіссерський режим і вільне полотно з блоків
Понад 25 моделей генерації
Генерація зображень, відео й аудіо
Автоматичне покращення підказок
Шаблони процесів
API на платних тарифах', 'From one sentence to script, storyboard and video
Director mode and free block canvas
25+ generation models
Image, video and audio generation
Automatic prompt improvement
Workflow templates
API on paid plans', 'Автори коротких відео й серіалів, маркетологи та невеликі студії.', 'Creators of short videos and series, marketers and small studios.', 'web', 'basic', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
