SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'vertechacademy.com' OR LOWER(`name`) = LOWER('Vertech Academy'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Vertech Academy', NULL, 'https://vertechacademy.com', NULL, NULL, 'AI-помічник для навчання й підготовки до тестів: перетворює незрозумілі лекції на практичні тести, дає миттєві пояснення й поєднує AI-репетиторів, курси та навчальні інструменти.', 'An AI study and test prep helper: it turns confusing lectures into practice tests, gives instant explanations and combines AI tutors, courses and study tools.', 'Vertech Academy зібрав в одному місці все, що потрібно учню чи студенту: AI-репетиторів, курси й інструменти, які допомагають розібратися в складних темах. Можна поставити запитання вчителю-універсалу — наприклад, чому небо блакитне чи що спричиняє землетруси — і отримати зрозуміле пояснення. Сервіс перетворює заплутані лекції на практичні тести й допомагає готуватися до іспитів. За даними сайту, в основі — підготовлені робочі процеси підказок для популярних AI-моделей. Вхід можливий через Google; є 14-денний безкоштовний пробний період із можливістю скасувати будь-коли.', 'Vertech Academy brings together everything a school or college student needs: AI tutors, courses and tools that help make sense of hard topics. You can ask a generalist teacher a question, for example why the sky is blue or what causes earthquakes, and get a clear explanation. The service turns confusing lectures into practice tests and helps you prepare for exams. According to the site, it is built on prepared prompt workflows for popular AI models. Sign-in with Google is available; there is a 14-day free trial that can be cancelled at any time.', 'AI-репетитори з різних предметів
Практичні тести з лекцій
Миттєві пояснення складних тем
Курси й навчальні інструменти
Вхід через Google', 'AI tutors for different subjects
Practice tests from lectures
Instant explanations of hard topics
Courses and study tools
Sign in with Google', 'Школярі й студенти, які готуються до занять і тестів.', 'School and college students preparing for classes and tests.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
