SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'younet.ai' OR LOWER(`name`) = LOWER('Younet'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Younet', NULL, 'https://younet.ai', NULL, NULL, 'Платформа AI-агентів для бізнесу: готові агенти для підтримки клієнтів, соцмереж, бізнес-стратегії, аналізу даних, генерації зображень і особистого асистента, з тисячами підключень до сервісів.', 'An AI agent platform for business: ready agents for customer support, social media, business strategy, data analysis, image generation and a personal assistant, with thousands of service connections.', 'Younet пропонує набір готових AI-агентів для реальної роботи: достатньо обрати агента й почати розмову. Агент підтримки клієнтів відповідає на звернення й веде тікети, менеджер соцмереж складає контент-план і публікації та аналізує Instagram, бізнес-стратег допомагає з бізнес-моделлю, презентаціями для інвесторів і довгостроковим плануванням, віртуальний асистент працює з поштою, розкладом і відстеженням прогресу, аналітик даних шукає тренди й неефективності, є й генератор зображень. Агенти можуть використовувати тисячі підключень до сервісів і набір навичок, а для простих запитів доступний звичайний чат. Платформа орієнтована як на стартапи, так і на компанії, з окремими рішеннями для великого бізнесу.', 'Younet offers a set of ready AI agents for real work: pick an agent and start a conversation. The customer support agent answers queries and manages tickets, the social media manager builds a content plan and posts and analyzes Instagram, the business strategist helps with the business model, investor decks and long-term planning, the virtual assistant handles email, schedules and progress tracking, the data analyst looks for trends and inefficiencies, and there is also an image generator. Agents can use thousands of service connections and a set of skills, and a plain chat is available for simple requests. The platform targets both startups and companies, with separate enterprise offerings.', 'Готові агенти під бізнес-завдання
Агент підтримки клієнтів
Агент для соцмереж
Бізнес-стратег і аналітик даних
Віртуальний асистент для пошти й розкладу
Тисячі підключень до сервісів', 'Ready agents for business tasks
Customer support agent
Social media agent
Business strategist and data analyst
Virtual assistant for email and schedule
Thousands of service connections', 'Засновники стартапів і компанії, які хочуть автоматизувати підтримку, маркетинг і аналітику агентами.', 'Startup founders and companies that want to automate support, marketing and analytics with agents.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
