-- Serno — Дослідження та пошук
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'serno.ai' OR LOWER(`name`) = LOWER('Serno'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Serno', NULL, 'https://serno.ai', NULL, NULL, 'AI-сервіс для складних запитань: під кожне запитання збирає команду з трьох-п''яти AI-експертів на різних моделях, які досліджують тему, сперечаються між собою й видають навігаційну карту висновків.', 'An AI service for complex questions: for each question it assembles a team of three to five AI experts on different models who research the topic, debate each other and deliver a navigable map of conclusions.', 'Serno призначений для запитань, над якими зазвичай працювала б ціла команда. Для кожного запиту сервіс формує команду з трьох-п''яти AI-експертів — кожен має свою роль, персону й завдання для дослідження та працює на моделі, підібраній під цю роботу, щоб сліпі зони однієї моделі перекривали інші. Коли експерти доходять протилежних висновків, Serno запускає структуровану дискусію з обов''язковим опонентом, яка має завершитися рішенням, а не розмитим підсумком. Результат подається не як суцільний звіт, а як карта Canvas, якою можна переміщатися й ставити уточнювальні запитання. Спробувати Canvas можна безкоштовно.', 'Serno is designed for questions that would normally take a whole team. For each request the service forms a team of three to five AI experts; each has its own role, persona and research brief and runs on a model chosen for the job, so the blind spots of one model are covered by others. When experts reach opposite conclusions, Serno starts a structured debate with a mandatory adversarial expert that has to end in a decision rather than a vague summary. The result is presented not as a wall of text but as a Canvas map you can navigate and ask follow-up questions about. You can try Canvas for free.', 'Команда з 3–5 AI-експертів під запитання
Різні моделі для різних ролей
Структуровані дебати при розбіжностях
Результат у вигляді карти Canvas
Уточнювальні запитання до результатів', 'A team of 3–5 AI experts per question
Different models for different roles
Structured debates on disagreements
Results as a Canvas map
Follow-up questions on results', 'Аналітики, засновники й дослідники, яким потрібен всебічний розбір складних питань.', 'Analysts, founders and researchers who need a thorough analysis of complex questions.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
