-- freebeat — Генерація відео
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'freebeat.ai' OR LOWER(`name`) = LOWER('freebeat'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'freebeat', NULL, 'https://freebeat.ai', NULL, NULL, 'AI-генератор музичних відео: з вашої пісні створює кліп, танцювальне відео чи lyric-відео з постійними персонажами, синхронізацією з ритмом і губами; є редактор, агент для правок у чаті, MCP і CLI.', 'An AI music video generator: from your song it creates a music video, dance video or lyric video with consistent characters, beat and lip sync; there is an editor, a chat agent for edits, MCP and a CLI.', 'freebeat перетворює музику на відео. Завантажте свій трек, і сервіс в один клік згенерує музичний кліп, танцювальне відео або відео з текстом пісні, точно синхронізоване з ритмом і рухами губ. Персонажі лишаються впізнаваними впродовж усього ролика, а творчий контроль залишається за вами. Окремий агент для музичних відео дозволяє редагувати будь-які деталі через чат. Також доступні режим реального часу, редагування музики, AI-відеоредактор, генерація зображень, відео й аудіо, відеоефекти та безкоштовні інструменти; для розробників є MCP і інструмент командного рядка. Нові користувачі отримують стартові безкоштовні кредити.', 'freebeat turns music into video. Upload your track and the service generates a music video, dance video or lyric video in one click, accurately synced to the beat and lip movements. Characters stay recognizable throughout the video, and you keep creative control. A dedicated music video agent lets you edit any detail through chat. There is also a real-time mode, music editing, an AI video editor, image, video and audio generation, video effects and free tools; developers get MCP and a command-line tool. New users receive free starter credits.', 'Музичні кліпи з вашого треку в один клік
Танцювальні й lyric-відео
Синхронізація з ритмом і губами
Постійні персонажі
Агент для правок через чат
AI-відеоредактор і ефекти
MCP і CLI', 'Music videos from your track in one click
Dance and lyric videos
Beat and lip sync
Consistent characters
Chat agent for edits
AI video editor and effects
MCP and CLI', 'Музиканти, продюсери й автори пісень, яким потрібні кліпи для своїх треків.', 'Musicians, producers and songwriters who need videos for their tracks.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
